/**
 * Email templates (plain text, Arabic first then an English paragraph). HTML is generated by MailService.
 * v2.1: left-to-right values inside Arabic sentences (ISO dates, amounts, invoice numbers, contact details) are
 * wrapped in Unicode isolates (LRI … PDI) so mail clients never render them reversed.
 */
import { Plan } from '@prisma/client';
import { isolate as L } from '../common/text';

/** Bank details printed in emails (from the invoice's seller snapshot or the current billing settings). */
export interface BankInfo {
  sellerName: string;
  bankName: string;
  iban: string;
}

export const CONTACT = { phone: '+966 55 042 1235', email: 'hello@shuoon.net', site: 'www.shuoon.net' } as const;

const PLAN_AR: Record<Plan, string> = { ESSENTIALS: 'الأساسية', GROWTH: 'النمو', ENTERPRISE: 'المؤسسات' };
const PLAN_EN: Record<Plan, string> = { ESSENTIALS: 'Essentials', GROWTH: 'Growth', ENTERPRISE: 'Enterprise' };
const STATUS_AR: Record<string, string> = { PENDING: 'بانتظار الموافقة', TRIAL: 'فترة تجريبية', ACTIVE: 'فعّال', SUSPENDED: 'موقوف', EXPIRED: 'منتهٍ' };
const METHOD_AR: Record<string, string> = { BANK_TRANSFER: 'تحويل بنكي', CARD: 'بطاقة', CASH: 'نقداً', OTHER: 'أخرى' };

export const sar = (n: number) => `${n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ر.س`;
const sarEn = (n: number) => `SAR ${n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const daysAr = (n: number) => (n === 0 ? 'اليوم' : n === 1 ? 'يوم واحد' : n === 2 ? 'يومان' : n <= 10 ? `${n} أيام` : `${n} يوماً`);
const daysEn = (n: number) => (n === 1 ? '1 day' : `${n} days`);

const SIGNATURE = [
  '—',
  'فريق شؤون | Shuoon Team',
  `جوال وواتساب: ${L(CONTACT.phone)}`,
  `البريد: ${L(CONTACT.email)}`,
  `الموقع: ${L(CONTACT.site)}`,
].join('\n');

const greet = (name: string | null) => (name ? `مرحباً ${name}،` : 'مرحباً،');
const greetEn = (name: string | null) => (name ? `Hello ${name},` : 'Hello,');

function compose(ar: string[], en: string[]): string {
  return [...ar, '', en.join('\n'), '', SIGNATURE].join('\n');
}

export interface EmailContent {
  subject: string;
  body: string;
}

export interface CompanyCtx {
  companyName: string;
  ownerName: string | null;
}

export function trialEndingEmail(c: CompanyCtx & { daysLeft: number; endDay: string }): EmailContent {
  return {
    subject: `تنتهي الفترة التجريبية لـ${c.companyName} خلال ${daysAr(c.daysLeft)} | Your Shuoon trial ends soon`,
    body: compose(
      [
        greet(c.ownerName),
        '',
        `نودّ تذكيرك بأن الفترة التجريبية لمنشأة «${c.companyName}» في شؤون تنتهي خلال ${daysAr(c.daysLeft)} (${L(c.endDay)}).`,
        'لمواصلة استخدام النظام دون انقطاع، تواصل معنا لتفعيل اشتراكك واختيار الباقة المناسبة.',
      ],
      [greetEn(c.ownerName), `Your Shuoon trial for "${c.companyName}" ends in ${daysEn(c.daysLeft)} (${c.endDay}). Contact us to activate your subscription and keep your data and access without interruption.`],
    ),
  };
}

export function subscriptionEndingEmail(c: CompanyCtx & { daysLeft: number; endDay: string; plan: Plan }): EmailContent {
  return {
    subject: `اشتراك ${c.companyName} ينتهي خلال ${daysAr(c.daysLeft)} | Your Shuoon subscription ends soon`,
    body: compose(
      [
        greet(c.ownerName),
        '',
        `نودّ تذكيرك بأن اشتراك منشأة «${c.companyName}» (باقة ${PLAN_AR[c.plan]}) ينتهي خلال ${daysAr(c.daysLeft)} بتاريخ ${L(c.endDay)}.`,
        'جدّد اشتراكك الآن لضمان استمرار الحضور والرواتب والإجازات دون توقف.',
      ],
      [greetEn(c.ownerName), `The ${PLAN_EN[c.plan]} subscription of "${c.companyName}" ends in ${daysEn(c.daysLeft)} (${c.endDay}). Renew now to keep attendance, payroll and leave running without interruption.`],
    ),
  };
}

export function expiredEmail(c: CompanyCtx & { endDay: string; wasTrial: boolean }): EmailContent {
  const what = c.wasTrial ? 'الفترة التجريبية' : 'الاشتراك';
  return {
    subject: `انتهى ${what} لـ${c.companyName} | Your Shuoon ${c.wasTrial ? 'trial' : 'subscription'} has ended`,
    body: compose(
      [
        greet(c.ownerName),
        '',
        `انتهى ${what} لمنشأة «${c.companyName}» في شؤون بتاريخ ${L(c.endDay)}، وتم إيقاف الدخول مؤقتاً.`,
        'بياناتك محفوظة بأمان — تواصل معنا للتجديد وستعود الخدمة فوراً.',
      ],
      [greetEn(c.ownerName), `The Shuoon ${c.wasTrial ? 'trial' : 'subscription'} of "${c.companyName}" ended on ${c.endDay} and access is paused. Your data is safe — contact us to renew and access is restored immediately.`],
    ),
  };
}

export interface InvoiceCtx {
  number: string;
  periodStart: string;
  periodEnd: string;
  total: number;
  dueDate: string;
  employees: number;
  plan: Plan;
  /** v2.1: TAX_INVOICE mentions VAT; INVOICE (seller not VAT-registered) does not */
  documentType?: 'TAX_INVOICE' | 'INVOICE' | 'CREDIT_NOTE';
}

function bankLines(b: BankInfo): string[] {
  const lines: string[] = [];
  if (b.bankName || b.iban) {
    lines.push('', 'بيانات التحويل:');
    if (b.bankName) lines.push(`البنك: ${b.bankName}`);
    if (b.iban) lines.push(`الآيبان: ${L(b.iban)}`);
    lines.push(`اسم المستفيد: ${b.sellerName}`);
  }
  return lines;
}

export function invoiceIssuedEmail(c: CompanyCtx & { invoice: InvoiceCtx; billing: BankInfo }): EmailContent {
  const i = c.invoice;
  const tax = i.documentType !== 'INVOICE';
  return {
    subject: `فاتورة جديدة ${i.number} — ${sar(i.total)} | New Shuoon invoice`,
    body: compose(
      [
        greet(c.ownerName),
        '',
        `صدرت فاتورة اشتراك منشأة «${c.companyName}» في شؤون:`,
        `رقم الفاتورة: ${L(i.number)}`,
        `الباقة: ${PLAN_AR[i.plan]} — ${L(i.employees)} موظف`,
        `الفترة: من ${L(i.periodStart)} إلى ${L(i.periodEnd)}`,
        `${tax ? 'الإجمالي شامل ضريبة القيمة المضافة' : 'الإجمالي'}: ${L(sar(i.total))}`,
        `تاريخ الاستحقاق: ${L(i.dueDate)}`,
        ...bankLines(c.billing),
        '',
        `يمكنك عرض الفاتورة وطباعتها من «الاشتراك والفواتير» في حسابك: ${L(`${CONTACT.site}/app/billing`)}`,
      ],
      [greetEn(c.ownerName), `Invoice ${i.number} for "${c.companyName}" (${i.periodStart} – ${i.periodEnd}) has been issued: ${sarEn(i.total)}${tax ? ' incl. VAT' : ''}, due ${i.dueDate}. View and print it under Subscription & invoices in your account.`],
    ),
  };
}

export function paymentReceivedEmail(c: CompanyCtx & { invoice: InvoiceCtx; paymentMethod: string; subscriptionEndsAt: string | null }): EmailContent {
  const i = c.invoice;
  return {
    subject: `تم استلام دفعتك — الفاتورة ${i.number} | Payment received`,
    body: compose(
      [
        greet(c.ownerName),
        '',
        `شكراً لك! استلمنا دفعة الفاتورة ${L(i.number)} بمبلغ ${L(sar(i.total))} (${METHOD_AR[c.paymentMethod] ?? c.paymentMethod}).`,
        ...(c.subscriptionEndsAt ? [`اشتراك منشأة «${c.companyName}» فعّال حتى ${L(c.subscriptionEndsAt)}.`] : []),
      ],
      [greetEn(c.ownerName), `Thank you! We received ${sarEn(i.total)} for invoice ${i.number}.${c.subscriptionEndsAt ? ` The subscription of "${c.companyName}" is active until ${c.subscriptionEndsAt}.` : ''}`],
    ),
  };
}

export function invoiceOverdueEmail(c: CompanyCtx & { invoice: InvoiceCtx; daysOverdue: number; billing: BankInfo }): EmailContent {
  const i = c.invoice;
  return {
    subject: `تذكير: الفاتورة ${i.number} متأخرة السداد | Invoice overdue`,
    body: compose(
      [
        greet(c.ownerName),
        '',
        `نودّ تذكيرك بأن الفاتورة ${L(i.number)} بمبلغ ${L(sar(i.total))} كانت مستحقة بتاريخ ${L(i.dueDate)} (متأخرة ${daysAr(c.daysOverdue)}).`,
        'نرجو إتمام السداد لتجنّب إيقاف الخدمة، وإن كنت قد سددت بالفعل فتجاهل هذه الرسالة.',
        ...bankLines(c.billing),
      ],
      [greetEn(c.ownerName), `Invoice ${i.number} (${sarEn(i.total)}) was due on ${i.dueDate} and is ${daysEn(c.daysOverdue)} overdue. Please settle it to avoid service interruption; if you have already paid, kindly ignore this message.`],
    ),
  };
}

export function manualReminderEmail(c: CompanyCtx & { plan: Plan; status: string; daysLeft: number | null; endDay: string | null; message?: string | null }): EmailContent {
  const left =
    c.daysLeft === null ? (c.endDay ? `ينتهي بتاريخ ${L(c.endDay)}` : 'غير محدد المدة') : `متبقٍ ${daysAr(c.daysLeft)}${c.endDay ? ` (حتى ${L(c.endDay)})` : ''}`;
  return {
    subject: `تذكير بخصوص اشتراك ${c.companyName} في شؤون | Shuoon subscription reminder`,
    body: compose(
      [
        greet(c.ownerName),
        '',
        ...(c.message?.trim() ? [c.message.trim(), ''] : []),
        'ملخص اشتراكك:',
        `الباقة: ${PLAN_AR[c.plan]}`,
        `الحالة: ${STATUS_AR[c.status] ?? c.status}`,
        `المدة المتبقية: ${left}`,
        '',
        'لأي استفسار أو للتجديد، يسعدنا تواصلك معنا.',
      ],
      [
        greetEn(c.ownerName),
        `A quick reminder about the Shuoon subscription of "${c.companyName}": plan ${PLAN_EN[c.plan]}, status ${c.status}${c.daysLeft !== null ? `, ${daysEn(c.daysLeft)} left` : ''}. Reach out any time to renew or ask a question.`,
      ],
    ),
  };
}
